        unit_price = _number(line.get("UNIT_PRC"))
        extension = _cents(quantity * unit_price)

        new_line["EXT_AMT"] = float(extension)
        total += extension

    discount = _number(order.get("DISC_PCT"))
    discounted = _cents(total * (Decimal("100") - discount) / Decimal("100"))

